// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

// Sinkronisasi field berdasarkan status area print
function syncAreaPrint() {
    const isAreaPrint = $formData.find('#print_area').val() === '1';
    const $areaPrintFields = $formData.find('#min_lebar, #max_lebar, #min_panjang');

    $formData.find('.area-print-required').toggle(isAreaPrint);
    $areaPrintFields.prop('disabled', !isAreaPrint);
    if (!isAreaPrint) $areaPrintFields.val('');
}

$('#print_toggle').on('change', function () {
    $formData.find('#print_area').val($(this).prop('checked') ? '1' : '0');
    syncAreaPrint();
});
syncAreaPrint();

// DataTables
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${thisUrl}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_tipe = $('#filter_tipe').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => simpan() },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    $('#filter_tipe').val('').trigger('change');

                    Swal.fire({
                        icon: "success",
                        title: "Informasi",
                        text: 'Selesai reload tabel ke kondisi awal',
                        showConfirmButton: false,
                        timer: 1300
                    }).then(function () { dt.ajax.reload(null, true); });
                }
            },
            {
                extend: 'excelHtml5',
                exportOptions: { columns: ':not(.no-export)' }
            }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 3, 4, 5, 6, 7, 8, 9], className: 'dt-body-center' },
            { targets: [7, 8], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data, 'waktu') } },
            { targets: 9, orderable: false },
        ]
    });

    // Custom dropdown filter
    $('#tabelData_filter.dataTables_filter').append($('#filter_tipe'));
    $(document).on('change', '#filter_tipe', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    // Reset Modal
    $modalDiv
        .on('shown.bs.modal', function () { formCek.resetInitial(); })
        .on('hidden.bs.modal', function () {
            CirebonwebForm.FormReset(this);
            $formData.find('#print_toggle').bootstrapToggle('off').trigger('change');
        });
});

// Form Submit (Insert/Update)
function simpan(id) {
    let $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${thisUrl}/simpan`;

    // Tentukan URL POST: Simpan atau Update
    if (id > 0) {
        CirebonwebForm.FormFetch(`${thisUrl}/getid`, { id }, 'POST', {})
            .done(function (response) {
                if (response.success) {
                    $modalTitle.text('Edit Data');
                    $btnSubmit.text('Update');

                    // Isi form
                    $formData.find('#id').val(response.data.id);
                    $formData.find('#mesin_tipe_id').val(response.data.mesin_tipe_id);
                    $formData.find('#nama').val(response.data.nama);
                    $formData.find('#print_area').val(response.data.print_area);
                    $formData.find('#min_lebar').val(response.data.min_lebar);
                    $formData.find('#max_lebar').val(response.data.max_lebar);
                    $formData.find('#min_panjang').val(response.data.min_panjang);
                    $formData.find('#print_toggle')
                        .bootstrapToggle(response.data.print_area == 1 ? 'on' : 'off')
                        .trigger('change');
                    $modalDiv.modal('show');
                }
            })
    } else {
        $('#id').val('');
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $formData.find('#print_toggle').bootstrapToggle('off').trigger('change');
        $modalDiv.modal('show');
    }

    // Form Validasi
    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            mesin_tipe_id: { required: true },
            nama: { required: true, minlength: 3, maxlength: 30 },
            print_area: { required: false, digits: true },
            min_lebar: { required: function () { return $formData.find('#print_area').val() === '1' }, minlength: 1, maxlength: 6 },
            max_lebar: { required: function () { return $formData.find('#print_area').val() === '1' }, minlength: 1, maxlength: 6 },
            min_panjang: { required: function () { return $formData.find('#print_area').val() === '1' }, minlength: 1, maxlength: 6 },
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;
            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Submit') }
            })
                .done(function (response) {
                    if (response.success) {
                        $modalDiv.modal('hide');
                        Swal.fire({
                            icon: "success",
                            title: "Sukses",
                            html: response.messages,
                            showConfirmButton: false,
                            timer: 1300
                        }).then(function () { $tabelData.DataTable().ajax.reload(null, false) })
                    }
                });
            return false; // Mencegah submit native
        }
    })
    )
}

// Form Submit (Delete)
function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${thisUrl}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}
